--!strict
local Players=game:GetService("Players");local ReplicatedStorage=game:GetService("ReplicatedStorage");local remotes=ReplicatedStorage:WaitForChild("Remotes",10);if not remotes then return end;local remote=remotes:WaitForChild("LeaderboardUpdated")::RemoteEvent;local gui=Instance.new("ScreenGui");gui.Name="LeaderboardGui";gui.ResetOnSpawn=false;gui.Parent=Players.LocalPlayer.PlayerGui;local label=Instance.new("TextLabel");label.Position=UDim2.fromScale(.02,.18);label.Size=UDim2.fromScale(.22,.48);label.BackgroundColor3=Color3.fromRGB(28,35,50);label.BackgroundTransparency=.15;label.TextColor3=Color3.new(1,1,1);label.TextSize=14;label.TextYAlignment=Enum.TextYAlignment.Top;label.Visible=false;label.Parent=gui
remote.OnClientEvent:Connect(function(data)local lines={"全球排行榜","","排位積分"};for _,x in data.rank do table.insert(lines,string.format("%d. %s  %d",x.rank,x.name,x.value))end;table.insert(lines,"\n競速勝場");for _,x in data.wins do table.insert(lines,string.format("%d. %s  %d",x.rank,x.name,x.value))end;table.insert(lines,"\nTower01 最快");for _,x in data.tower do table.insert(lines,string.format("%d. %s  %.2fs",x.rank,x.name,x.value/1000))end;label.Text=table.concat(lines,"\n");label.Visible=true end)
